<template>
  <view class="page" v-if="plan">
    <view class="hero">
      <view class="hero-top"><view><view class="kicker">计划详情</view><view class="title">{{ plan.title }}</view></view><view class="pill">{{ statusText(plan.status) }}</view></view>
      <view class="description">{{ plan.description || '暂无计划说明' }}</view><view class="range">{{ plan.start_date }} 至 {{ plan.end_date }} · 每周 {{ plan.weekly_target_hours }} 小时</view>
      <view class="progress-copy"><text>完成 {{ completed }}/{{ tasks.length }}</text><text>{{ progress }}%</text></view><view class="track"><view class="fill" :style="{ width: `${progress}%` }" /></view>
    </view>

    <view class="operation-card">
      <view class="operation-copy"><view class="operation-title">{{ plan.status === 'paused' ? '计划暂时休息中' : '保持学习节奏' }}</view><view class="operation-desc">{{ plan.status === 'paused' ? '恢复后继续按当前日程推进' : '需要休息时可以暂停，任务记录不会丢失' }}</view></view>
      <button class="lifecycle" @click="toggleStatus">{{ plan.status === 'paused' ? '恢复计划' : '暂停计划' }}</button>
      <view class="secondary-actions"><button @click="openPlanEdit">编辑计划</button><button @click="openInvite">邀请伙伴</button><button @click="showMore = true">更多操作</button></view>
    </view>

    <view class="properties"><view><text>学习日</text><view class="property-value">{{ weekdaySummary(plan.study_weekdays) }}</view></view><view><text>默认时段</text><view class="property-value">{{ plan.default_planned_start }}-{{ plan.default_planned_end }}</view></view><view><text>小组可见</text><view class="property-value">{{ plan.public_to_group ? '是' : '否' }}</view></view><view><text>来源</text><view class="property-value">{{ generationSource(plan) }}</view></view></view>
    <view class="section-head"><view>任务安排</view><button @click="openTaskEdit()">＋ 新建任务</button></view>
    <view class="empty" v-if="!tasks.length">这个计划还没有任务</view>
    <view class="task" v-for="task in tasks" :key="task.id" @click="openTask(task)"><view class="task-date">{{ task.date }} · {{ task.planned_start }}-{{ task.planned_end }}</view><view class="task-head"><view class="task-title">{{ task.title }}</view><view class="task-status">{{ taskStatus(task.status) }}</view></view><view class="objective">{{ task.objective }}</view><view class="task-actions" @click.stop><button @click="openTaskEdit(task)">编辑</button><button class="danger" v-if="task.status !== 'in_progress'" @click="removeTask(task)">删除</button></view></view>

    <view class="sheet" v-if="showMore" @click.self="showMore = false"><view class="sheet-body compact-sheet"><view class="sheet-title">更多操作</view><button class="sheet-option" @click="openDelay">延期计划<text>整体顺延未完成任务</text></button><view class="destructive-section"><view class="destructive-label">谨慎操作</view><button class="sheet-option danger-option" @click="removePlan">删除计划<text>同时删除任务和打卡历史</text></button></view><button class="cancel" @click="showMore = false">取消</button></view></view>
    <view class="sheet" v-if="planEditing" @click.self="planEditing = false"><view class="sheet-body"><view class="sheet-title">编辑计划</view><view class="field"><text>名称</text><input v-model="planForm.title" /></view><view class="field"><text>说明</text><textarea v-model="planForm.description" /></view><view class="field"><text>每周目标小时</text><input type="number" v-model.number="planForm.weekly_target_hours" /></view>
      <view class="schedule-card"><view class="schedule-title">日程模板</view><view class="schedule-note">调整后，未完成任务将按模板重新计算；日期特殊时段会原样保留并优先使用。</view><view class="field"><text>默认时段</text><view class="time-grid"><picker mode="time" :value="planForm.default_planned_start" @change="setPlanTime('default_planned_start', $event)"><view class="picker">{{ planForm.default_planned_start }}</view></picker><picker mode="time" :value="planForm.default_planned_end" @change="setPlanTime('default_planned_end', $event)"><view class="picker">{{ planForm.default_planned_end }}</view></picker></view></view>
        <view class="field"><text>学习日</text><view class="weekdays"><view v-for="day in weekdays" :key="day.value" :class="['weekday', { selected: planForm.study_weekdays.includes(day.value) }]" @click="toggleWeekday(day.value)">{{ day.label }}</view></view></view>
        <view class="override" v-for="day in selectedWeekdays" :key="day.value"><view><view class="override-name">周{{ day.label }}</view><view class="override-copy">{{ weekdayOverride(day.value) ? '使用自定义时段' : '使用默认时段' }}</view></view><switch color="#ff7aa2" :checked="Boolean(weekdayOverride(day.value))" @change="setOverrideEnabled(day.value, $event)" /><view class="time-grid override-times" v-if="weekdayOverride(day.value)"><picker mode="time" :value="weekdayOverride(day.value)?.planned_start" @change="setOverrideTime(day.value, 'planned_start', $event)"><view class="picker">{{ weekdayOverride(day.value)?.planned_start }}</view></picker><picker mode="time" :value="weekdayOverride(day.value)?.planned_end" @change="setOverrideTime(day.value, 'planned_end', $event)"><view class="picker">{{ weekdayOverride(day.value)?.planned_end }}</view></picker></view></view>
      </view><view class="sheet-actions"><button class="secondary" @click="planEditing = false">取消</button><button class="primary" @click="savePlan">保存</button></view></view></view>
    <view class="sheet" v-if="taskEditing" @click.self="taskEditing = false"><view class="sheet-body"><view class="sheet-title">{{ taskForm.id ? '编辑任务' : '新建任务' }}</view><view class="field"><text>日期</text><picker mode="date" :value="taskForm.date" @change="taskForm.date = $event.detail.value"><view class="picker">{{ taskForm.date }}</view></picker></view><view class="field"><text>标题</text><input v-model="taskForm.title" /></view><view class="field"><text>目标</text><textarea v-model="taskForm.objective" /></view><view class="field"><text>说明</text><textarea v-model="taskForm.description" /></view><view class="time-grid"><picker mode="time" :value="taskForm.planned_start" @change="taskForm.planned_start = $event.detail.value"><view class="picker">{{ taskForm.planned_start }}</view></picker><picker mode="time" :value="taskForm.planned_end" @change="taskForm.planned_end = $event.detail.value"><view class="picker">{{ taskForm.planned_end }}</view></picker></view><view class="sheet-actions"><button class="secondary" @click="taskEditing = false">取消</button><button class="primary" @click="saveTask">保存</button></view></view></view>
    <view class="sheet" v-if="inviting" @click.self="inviting = false"><view class="sheet-body"><view class="sheet-title">按昵称邀请</view><input v-model="query" placeholder="至少输入 2 个字符" @input="search" /><view class="candidate" v-for="user in results" :key="user.invite_target_id" @click="sendInvite(user)">{{ user.nickname }}<text>邀请</text></view><view class="empty" v-if="query.length >= 2 && !searching && !results.length">没有找到匹配用户</view></view></view>
  </view>
</template>

<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { PlanApi, StudyTaskApi, UserApi, type Plan, type ScheduleOverride, type TimerTask, type UserSearchResult } from '@/api'
import { localDateKey } from '@/utils/date'

const weekdays = [{ value: 1, label: '一' }, { value: 2, label: '二' }, { value: 3, label: '三' }, { value: 4, label: '四' }, { value: 5, label: '五' }, { value: 6, label: '六' }, { value: 7, label: '日' }]
const planId = ref(0), plan = ref<Plan | null>(null), tasks = ref<TimerTask[]>([]), planEditing = ref(false), taskEditing = ref(false), inviting = ref(false), showMore = ref(false), query = ref(''), results = ref<UserSearchResult[]>([]), searching = ref(false)
const planForm = reactive({ title: '', description: '', weekly_target_hours: 0, default_planned_start: '20:00', default_planned_end: '21:00', study_weekdays: [] as number[] })
const weekdayOverrides = ref<ScheduleOverride[]>([]), dateOverrides = ref<ScheduleOverride[]>([])
const taskForm = reactive({ id: 0, date: '', title: '', objective: '', description: '', planned_start: '20:00', planned_end: '21:00' })
const completed = computed(() => tasks.value.filter(task => task.status === 'completed').length), progress = computed(() => tasks.value.length ? Math.round(completed.value / tasks.value.length * 100) : 0)
const selectedWeekdays = computed(() => weekdays.filter(day => planForm.study_weekdays.includes(day.value)))
let searchTimer: ReturnType<typeof setTimeout> | null = null

onLoad((options: any) => { planId.value = Number(options?.id || 0); if (options?.invite === '1') inviting.value = true })
onShow(load)

async function load() { if (!planId.value) return; try { const [detail, rows] = await Promise.all([PlanApi.get(planId.value), PlanApi.tasks(planId.value)]); plan.value = detail; tasks.value = rows || [] } catch (error: any) { uni.showToast({ title: error?.message || '加载失败', icon: 'none' }) } }
function openPlanEdit() { if (!plan.value) return; Object.assign(planForm, { title: plan.value.title, description: plan.value.description || '', weekly_target_hours: plan.value.weekly_target_hours, default_planned_start: plan.value.default_planned_start, default_planned_end: plan.value.default_planned_end, study_weekdays: [...(plan.value.study_weekdays || [])] }); weekdayOverrides.value = (plan.value.schedule_overrides || []).filter(row => row.weekday).map(copyOverride); dateOverrides.value = (plan.value.schedule_overrides || []).filter(row => row.date).map(copyOverride); planEditing.value = true }
function copyOverride(row: ScheduleOverride): ScheduleOverride { return { weekday: row.weekday, date: row.date, planned_start: row.planned_start, planned_end: row.planned_end } }
function toggleWeekday(value: number) { planForm.study_weekdays = planForm.study_weekdays.includes(value) ? planForm.study_weekdays.filter(day => day !== value) : [...planForm.study_weekdays, value].sort() }
function weekdayOverride(value: number) { return weekdayOverrides.value.find(row => row.weekday === value) }
function toggleOverride(value: number, enabled: boolean) { if (enabled && !weekdayOverride(value)) weekdayOverrides.value.push({ weekday: value, planned_start: planForm.default_planned_start, planned_end: planForm.default_planned_end }); if (!enabled) weekdayOverrides.value = weekdayOverrides.value.filter(row => row.weekday !== value) }
function setOverrideEnabled(value: number, event: any) { toggleOverride(value, event.detail.value) }
function setPlanTime(field: 'default_planned_start' | 'default_planned_end', event: any) { planForm[field] = event.detail.value }
function setOverrideTime(value: number, field: 'planned_start' | 'planned_end', event: any) { const row = weekdayOverride(value); if (row) row[field] = event.detail.value }
function scheduleChanged() { if (!plan.value) return false; const normalize = (rows: ScheduleOverride[]) => rows.map(copyOverride).sort((a, b) => (a.weekday || 0) - (b.weekday || 0) || String(a.date || '').localeCompare(String(b.date || ''))); return planForm.default_planned_start !== plan.value.default_planned_start || planForm.default_planned_end !== plan.value.default_planned_end || JSON.stringify(planForm.study_weekdays) !== JSON.stringify(plan.value.study_weekdays || []) || JSON.stringify(normalize(weekdayOverrides.value)) !== JSON.stringify(normalize((plan.value.schedule_overrides || []).filter(row => row.weekday))) }
async function savePlan() {
  if (!planForm.title.trim()) return void uni.showToast({ title: '请填写计划名称', icon: 'none' })
  if (!planForm.study_weekdays.length && !plan.value?.study_dates?.length) return void uni.showToast({ title: '请至少选择一个学习日', icon: 'none' })
  if (planForm.default_planned_start >= planForm.default_planned_end || weekdayOverrides.value.some(row => row.planned_start >= row.planned_end)) return void uni.showToast({ title: '结束时间必须晚于开始时间', icon: 'none' })
  const changed = scheduleChanged()
  if (changed) { const pending = tasks.value.filter(task => task.status === 'pending').length, running = tasks.value.filter(task => task.status === 'in_progress').length; const content = `保存后将重新计算 ${pending} 个待执行任务${running ? `和 ${running} 个学习中任务` : ''}的计划时段；${completed.value} 个已完成任务保持不变。日期特殊时段也会保留。`; if (!await confirm('确认调整日程', content)) return }
  const data: Partial<Plan> = { title: planForm.title, description: planForm.description, weekly_target_hours: planForm.weekly_target_hours }
  if (changed) Object.assign(data, { default_planned_start: planForm.default_planned_start, default_planned_end: planForm.default_planned_end, study_weekdays: planForm.study_weekdays, schedule_overrides: [...weekdayOverrides.value.map(copyOverride), ...dateOverrides.value.map(copyOverride)] })
  try { plan.value = await PlanApi.update(planId.value, data); planEditing.value = false; await load() } catch (error: any) { uni.showToast({ title: error?.message || '保存失败', icon: 'none' }) }
}
function openTaskEdit(task?: TimerTask) { Object.assign(taskForm, task ? { id: task.id, date: task.date, title: task.title, objective: task.objective, description: task.description || '', planned_start: task.planned_start || '20:00', planned_end: task.planned_end || '21:00' } : { id: 0, date: plan.value?.start_date || localDateKey(), title: '', objective: '', description: '', planned_start: plan.value?.default_planned_start || '20:00', planned_end: plan.value?.default_planned_end || '21:00' }); taskEditing.value = true }
async function saveTask() { if (!taskForm.title.trim() || !taskForm.objective.trim() || taskForm.planned_start >= taskForm.planned_end) return void uni.showToast({ title: '请完整填写有效任务信息', icon: 'none' }); const data = { date: taskForm.date, title: taskForm.title, objective: taskForm.objective, description: taskForm.description, planned_start: taskForm.planned_start, planned_end: taskForm.planned_end }; try { taskForm.id ? await StudyTaskApi.update(taskForm.id, data) : await PlanApi.createTask(planId.value, data); taskEditing.value = false; await load() } catch (error: any) { uni.showToast({ title: error?.message || '保存失败', icon: 'none' }) } }
async function toggleStatus() { if (!plan.value) return; const pausing = plan.value.status !== 'paused'; if (!await confirm(pausing ? '暂停计划' : '恢复计划', pausing ? '暂停后计划和记录会保留，你可以随时恢复。' : '恢复后将继续按当前日程推进计划。')) return; try { plan.value = pausing ? await PlanApi.pause(planId.value) : await PlanApi.resume(planId.value) } catch (error: any) { uni.showToast({ title: error?.message || '操作失败', icon: 'none' }) } }
function openDelay() { showMore.value = false; delay() }
async function delay() { const result = await new Promise<any>(resolve => uni.showActionSheet({ itemList: ['延期 1 天', '延期 3 天', '延期 7 天'], success: resolve, fail: () => resolve(null) })); if (!result) return; const days = [1, 3, 7][result.tapIndex]; uni.navigateTo({ url: `/pages/recovery/recovery?mode=plan_shift&plan_id=${planId.value}&days=${days}` }) }
async function removePlan() { if (!plan.value) return; showMore.value = false; if (!await confirm('删除计划', `将删除「${plan.value.title}」及其任务和打卡历史。`)) return; try { await PlanApi.remove(planId.value); uni.navigateBack() } catch (error: any) { uni.showToast({ title: error?.message || '删除失败', icon: 'none' }) } }
async function removeTask(task: TimerTask) { if (!await confirm('删除任务', `确认删除「${task.title}」？`)) return; try { await StudyTaskApi.remove(task.id); await load() } catch (error: any) { uni.showToast({ title: error?.message || '删除失败', icon: 'none' }) } }
function confirm(title: string, content: string) { return new Promise<boolean>(resolve => uni.showModal({ title, content, confirmColor: '#c95668', success: result => resolve(result.confirm) })) }
function openInvite() { query.value = ''; results.value = []; inviting.value = true }
function search() { if (searchTimer) clearTimeout(searchTimer); results.value = []; if (query.value.trim().length < 2) return; searchTimer = setTimeout(async () => { searching.value = true; try { results.value = await UserApi.search(query.value.trim()) } finally { searching.value = false } }, 300) }
async function sendInvite(user: UserSearchResult) { try { await PlanApi.invite(planId.value, user.invite_target_id); inviting.value = false; uni.showToast({ title: '邀请已发送', icon: 'success' }) } catch (error: any) { uni.showToast({ title: error?.message || '邀请失败', icon: 'none' }) } }
function openTask(task: TimerTask) { uni.navigateTo({ url: `/pages/task/task?id=${task.id}` }) }
function generationSource(value: Plan) { if (value.generation_source === 'ai_decomposed') return 'AI 任务拆解'; if (value.generation_source === 'local_enriched') return 'AI 增强'; if (value.generation_source === 'local') return '本地智能规划'; return value.ai_generated ? '历史 AI 生成' : '手动创建' }
function statusText(status: string) { return status === 'paused' ? '已暂停' : status === 'archived' ? '已归档' : '进行中' }
function taskStatus(status: string) { return status === 'completed' ? '已完成' : status === 'in_progress' ? '学习中' : '待执行' }
function weekdaySummary(selected: number[] = []) { return selected.length === 7 ? '每天' : selected.length ? `周${selected.map(value => weekdays.find(day => day.value === value)?.label).join('、')}` : '按指定日期' }
</script>

<style lang="scss">
.page{min-height:100vh;box-sizing:border-box;padding:28rpx 28rpx 70rpx;background:linear-gradient(180deg,#fff0f7,#fffaf0 44%,#f7fbff);color:#4b2b3f}.hero{padding:34rpx;border-radius:34rpx;background:linear-gradient(135deg,#ff8fab,#ffc36a);color:#fff;box-shadow:0 18rpx 42rpx rgba(255,143,171,.2)}.hero-top,.progress-copy,.task-head,.section-head{display:flex;align-items:center;justify-content:space-between;gap:16rpx}.kicker{font-size:22rpx}.title{margin-top:8rpx;font-size:40rpx;font-weight:900}.pill{padding:9rpx 16rpx;border-radius:99rpx;background:#ffffff35}.description,.range{margin-top:16rpx;font-size:24rpx;line-height:1.5}.progress-copy{margin-top:24rpx}.track{height:14rpx;margin-top:10rpx;border-radius:99rpx;background:#ffffff45;overflow:hidden}.fill{height:100%;background:#fff}.operation-card{margin-top:18rpx;padding:28rpx;border-radius:28rpx;background:#fff;border:1rpx solid #ffe0ea;box-shadow:0 12rpx 28rpx rgba(255,143,171,.08)}.operation-title{font-size:29rpx;font-weight:900}.operation-desc{margin-top:8rpx;color:#7b8498;font-size:22rpx;line-height:1.5}.lifecycle{margin:24rpx 0 0;border-radius:99rpx;background:linear-gradient(135deg,#ff769f,#ff9f69);color:#fff;font-weight:900}.secondary-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:10rpx;margin-top:12rpx}.secondary-actions button,.task-actions button{margin:0;padding:0 8rpx;background:#fff5f8;color:#b85b79;font-size:22rpx}.properties{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:18rpx}.properties>view{padding:22rpx;border-radius:20rpx;background:#fff}.properties text{display:block;color:#8a92a6;font-size:21rpx}.property-value{margin-top:7rpx;font-size:24rpx;font-weight:700}.section-head{margin:32rpx 4rpx 16rpx;font-size:31rpx;font-weight:900}.section-head button{margin:0;background:#fff0f6;color:#ff6f91;font-size:22rpx}.task{margin-bottom:16rpx;padding:26rpx;border-radius:26rpx;background:#fff;border:1rpx solid #ffe0ea}.task-date{color:#9a6176;font-size:22rpx}.task-head{margin-top:10rpx}.task-title{font-size:29rpx;font-weight:900}.task-status{color:#ff6f91;font-size:21rpx}.objective{margin-top:10rpx;color:#606a80;font-size:24rpx;line-height:1.5}.task-actions{display:flex;justify-content:flex-end;gap:10rpx;margin-top:16rpx}.task-actions button{height:54rpx;line-height:54rpx}.danger{color:#bd5361!important}.empty{padding:30rpx;color:#8a92a6;text-align:center}.sheet{position:fixed;inset:0;z-index:99;display:flex;align-items:flex-end;background:#30223388}.sheet-body{width:100%;max-height:86vh;box-sizing:border-box;padding:34rpx 28rpx 46rpx;border-radius:34rpx 34rpx 0 0;background:#fff;overflow-y:auto}.compact-sheet{padding-bottom:34rpx}.sheet-title{margin-bottom:24rpx;font-size:32rpx;font-weight:900}.field{margin-top:18rpx}.field>text{display:block;margin-bottom:8rpx;color:#7b8498;font-size:22rpx}.field input,.field textarea,.picker,.candidate{box-sizing:border-box;width:100%;padding:20rpx;border-radius:18rpx;background:#f7f8fb}.field textarea{height:120rpx}.time-grid{display:grid;grid-template-columns:1fr 1fr;gap:12rpx}.sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:12rpx;margin-top:26rpx}.sheet-actions button{margin:0}.secondary,.cancel{background:#f3f5f8;color:#606a80}.primary{background:#ff7aa2;color:#fff}.schedule-card{margin-top:24rpx;padding:24rpx;border-radius:24rpx;background:#fff8fb;border:1rpx solid #ffe1eb}.schedule-title{font-size:27rpx;font-weight:900}.schedule-note{margin-top:8rpx;color:#8a7180;font-size:21rpx;line-height:1.55}.weekdays{display:flex;justify-content:space-between;gap:8rpx}.weekday{display:flex;align-items:center;justify-content:center;width:58rpx;height:58rpx;border-radius:50%;background:#fff;color:#8a92a6;font-size:22rpx}.weekday.selected{background:#ff7aa2;color:#fff;font-weight:900}.override{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12rpx;padding:20rpx 0;border-top:1rpx solid #ffe5ed}.override-name{font-size:24rpx;font-weight:800}.override-copy{margin-top:4rpx;color:#8a92a6;font-size:20rpx}.override-times{width:100%}.sheet-option{display:flex;align-items:center;justify-content:space-between;margin-top:12rpx;background:#f7f8fb;color:#4b2b3f;text-align:left}.sheet-option text{color:#8a92a6;font-size:21rpx;font-weight:400}.destructive-section{margin-top:28rpx;padding-top:22rpx;border-top:1rpx solid #eef1f5}.destructive-label{color:#a4a8b2;font-size:20rpx}.danger-option{background:#fff8f8;color:#b95b68}.compact-sheet>.cancel{margin-top:20rpx}.candidate{display:flex;justify-content:space-between;margin-top:12rpx}.candidate text{color:#ff6f91}
</style>
